import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.LX5S0jbT.js";const u=JSON.parse('{"title":"快捷键参考","description":"","frontmatter":{},"headers":[],"relativePath":"zh/keybindings.md","filePath":"zh/keybindings.md"}'),r={name:"zh/keybindings.md"};function a(i,t,s,l,n,p){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="快捷键参考" tabindex="-1">快捷键参考 <a class="header-anchor" href="#快捷键参考" aria-label="Permalink to &quot;快捷键参考&quot;">​</a></h1><p>Pi 暴露可绑定快捷键的命名操作，例如 <code>app.session.new</code>。你可以在 Pi 的<a href="./configuration.html#agent-directory">用户配置</a>中更改默认绑定，或为未绑定的操作添加绑定。</p><p>运行 <code>/hotkeys</code> 查看主编辑器和应用的当前快捷键。</p><p><a id="assign-keybindings"></a></p><h2 id="绑定快捷键" tabindex="-1">绑定快捷键 <a class="header-anchor" href="#绑定快捷键" aria-label="Permalink to &quot;绑定快捷键&quot;">​</a></h2><p>创建 <code>&lt;agent-dir&gt;/keybindings.json</code>。agent 目录默认为 <code>~/.pi/agent</code>，详见 <a href="./configuration.html#agent-directory">Agent 目录</a>。</p><p>将每个操作标识符映射到一个键或键列表：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://pi.dev/schemas/keybindings.schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;app.session.new&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ctrl+shift+n&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;app.session.tree&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ctrl+shift+t&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alt+shift+t&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>配置值会替换该操作的默认值。使用空列表禁用某操作的快捷键：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tui.altScreen.pageUp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>编辑文件后，运行 <code>/reload</code> 将更改应用到当前会话。</p><h2 id="键语法" tabindex="-1">键语法 <a class="header-anchor" href="#键语法" aria-label="Permalink to &quot;键语法&quot;">​</a></h2><p>按键写作 <code>modifier+key</code>。修饰键是 <code>ctrl</code>、<code>shift</code>、<code>alt</code> 和 <code>super</code>。可以组合修饰键。有效的按键有：</p><ul><li><strong>字母：</strong> <code>a-z</code></li><li><strong>数字：</strong> <code>0-9</code></li><li><strong>特殊键：</strong> <code>escape</code>, <code>esc</code>, <code>enter</code>, <code>return</code>, <code>tab</code>, <code>space</code>, <code>backspace</code>, <code>delete</code>, <code>insert</code>, <code>clear</code>, <code>home</code>, <code>end</code>, <code>pageUp</code>, <code>pageDown</code>, <code>up</code>, <code>down</code>, <code>left</code>, <code>right</code></li><li><strong>功能键：</strong> <code>f1</code>-<code>f12</code></li><li><strong>符号：</strong> <code>\`</code>, <code>-</code>, <code>=</code>, <code>[</code>, <code>]</code>, <code>\\</code>, <code>;</code>, <code>&#39;</code>, <code>,</code>, <code>.</code>, <code>/</code>, <code>!</code>, <code>@</code>, <code>#</code>, <code>$</code>, <code>%</code>, <code>^</code>, <code>&amp;</code>, <code>*</code>, <code>(</code>, <code>)</code>, <code>_</code>, <code>+</code>, <code>|</code>, <code>~</code>, <code>{</code>, <code>}</code>, <code>:</code>, <code>&lt;</code>, <code>&gt;</code>, <code>?</code></li></ul><p>示例：<code>ctrl+shift+x</code>、<code>alt+ctrl+x</code>、<code>ctrl+shift+alt+x</code>、<code>super+k</code>、<code>ctrl+super+k</code> 和 <code>ctrl+1</code>。</p><p><code>super</code> 绑定要求终端单独上报该修饰键，通常通过 Kitty 键盘协议。在不支持该功能的终端中可能无效。</p><h2 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h2><h3 id="终端-ui" tabindex="-1">终端 UI <a class="header-anchor" href="#终端-ui" aria-label="Permalink to &quot;终端 UI&quot;">​</a></h3><h4 id="光标移动" tabindex="-1">光标移动 <a class="header-anchor" href="#光标移动" aria-label="Permalink to &quot;光标移动&quot;">​</a></h4><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>tui.editor.cursorUp</code></td><td><code>up</code></td><td>上移光标，在顶部时浏览更早的历史</td></tr><tr><td><code>tui.editor.cursorDown</code></td><td><code>down</code></td><td>下移光标，在底部时浏览更新的历史</td></tr><tr><td><code>tui.editor.historyPrevious</code></td><td>无</td><td>选择上一条提示历史条目</td></tr><tr><td><code>tui.editor.historyNext</code></td><td>无</td><td>选择下一条提示历史条目</td></tr><tr><td><code>tui.editor.cursorLeft</code></td><td><code>left</code>, <code>ctrl+b</code></td><td>左移光标</td></tr><tr><td><code>tui.editor.cursorRight</code></td><td><code>right</code>, <code>ctrl+f</code></td><td>右移光标</td></tr><tr><td><code>tui.editor.cursorWordLeft</code></td><td><code>alt+left</code>, <code>ctrl+left</code>, <code>alt+b</code></td><td>光标左移一个词</td></tr><tr><td><code>tui.editor.cursorWordRight</code></td><td><code>alt+right</code>, <code>ctrl+right</code>, <code>alt+f</code></td><td>光标右移一个词</td></tr><tr><td><code>tui.editor.cursorLineStart</code></td><td><code>home</code>, <code>ctrl+a</code></td><td>移到行首</td></tr><tr><td><code>tui.editor.cursorLineEnd</code></td><td><code>end</code>, <code>ctrl+e</code></td><td>移到行尾</td></tr><tr><td><code>tui.editor.jumpForward</code></td><td><code>ctrl+]</code></td><td>向前跳到某字符</td></tr><tr><td><code>tui.editor.jumpBackward</code></td><td><code>ctrl+alt+]</code></td><td>向后跳到某字符</td></tr><tr><td><code>tui.editor.pageUp</code></td><td><code>pageUp</code>, <code>ctrl+pageUp</code></td><td>向上翻页</td></tr><tr><td><code>tui.editor.pageDown</code></td><td><code>pageDown</code>, <code>ctrl+pageDown</code></td><td>向下翻页</td></tr></tbody></table><p>专用的历史操作无论光标位置如何都会浏览提示历史，并优先于使用相同按键的应用操作。</p><h4 id="文本编辑" tabindex="-1">文本编辑 <a class="header-anchor" href="#文本编辑" aria-label="Permalink to &quot;文本编辑&quot;">​</a></h4><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>tui.editor.deleteCharBackward</code></td><td><code>backspace</code></td><td>向后删除字符</td></tr><tr><td><code>tui.editor.deleteCharForward</code></td><td><code>delete</code>, <code>ctrl+d</code></td><td>向前删除字符</td></tr><tr><td><code>tui.editor.deleteWordBackward</code></td><td><code>ctrl+w</code>, <code>alt+backspace</code></td><td>向后删除一个词</td></tr><tr><td><code>tui.editor.deleteWordForward</code></td><td><code>alt+d</code>, <code>alt+delete</code></td><td>向前删除一个词</td></tr><tr><td><code>tui.editor.deleteToLineStart</code></td><td><code>ctrl+u</code></td><td>删除到行首</td></tr><tr><td><code>tui.editor.deleteToLineEnd</code></td><td><code>ctrl+k</code></td><td>删除到行尾</td></tr><tr><td><code>tui.editor.yank</code></td><td><code>ctrl+y</code></td><td>粘贴最近删除的文本</td></tr><tr><td><code>tui.editor.yankPop</code></td><td><code>alt+y</code></td><td>在 yank 之后循环切换先前删除的文本</td></tr><tr><td><code>tui.editor.undo</code></td><td><code>ctrl+-</code>（Windows 上为 <code>ctrl+z</code>；WSL 上为 <code>alt+z</code>）</td><td>撤销上一次编辑</td></tr></tbody></table><h4 id="输入与选择" tabindex="-1">输入与选择 <a class="header-anchor" href="#输入与选择" aria-label="Permalink to &quot;输入与选择&quot;">​</a></h4><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>tui.input.newLine</code></td><td><code>shift+enter</code>, <code>ctrl+j</code></td><td>插入新行</td></tr><tr><td><code>tui.input.submit</code></td><td><code>enter</code></td><td>提交输入</td></tr><tr><td><code>tui.input.tab</code></td><td><code>tab</code></td><td>制表或自动补全</td></tr><tr><td><code>tui.input.copy</code></td><td><code>ctrl+c</code></td><td>复制选区</td></tr><tr><td><code>tui.select.up</code></td><td><code>up</code></td><td>选择项上移</td></tr><tr><td><code>tui.select.down</code></td><td><code>down</code></td><td>选择项下移</td></tr><tr><td><code>tui.select.pageUp</code></td><td><code>pageUp</code></td><td>列表上翻一页</td></tr><tr><td><code>tui.select.pageDown</code></td><td><code>pageDown</code></td><td>列表下翻一页</td></tr><tr><td><code>tui.select.confirm</code></td><td><code>enter</code></td><td>确认选择</td></tr><tr><td><code>tui.select.cancel</code></td><td><code>escape</code>, <code>ctrl+c</code></td><td>取消选择</td></tr></tbody></table><h4 id="全屏" tabindex="-1">全屏 <a class="header-anchor" href="#全屏" aria-label="Permalink to &quot;全屏&quot;">​</a></h4><p>在全屏模式下，这些操作控制对话记录，并优先于使用相同按键的编辑器操作。</p><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>tui.altScreen.pageUp</code></td><td><code>pageUp</code></td><td>对话记录向上滚动一页</td></tr><tr><td><code>tui.altScreen.pageDown</code></td><td><code>pageDown</code></td><td>对话记录向下滚动一页</td></tr><tr><td><code>tui.altScreen.halfPageUp</code></td><td>无</td><td>对话记录向上滚动半页</td></tr><tr><td><code>tui.altScreen.halfPageDown</code></td><td>无</td><td>对话记录向下滚动半页</td></tr><tr><td><code>tui.altScreen.lineUp</code></td><td>无</td><td>对话记录向上滚动一行</td></tr><tr><td><code>tui.altScreen.lineDown</code></td><td>无</td><td>对话记录向下滚动一行</td></tr><tr><td><code>tui.altScreen.previousPrompt</code></td><td><code>ctrl+shift+up</code>, <code>ctrl+up</code>（Windows 和 WSL 上仅 <code>ctrl+up</code>）</td><td>跳到上一个标记的消息</td></tr><tr><td><code>tui.altScreen.nextPrompt</code></td><td><code>ctrl+shift+down</code>, <code>ctrl+down</code>（Windows 和 WSL 上仅 <code>ctrl+down</code>）</td><td>跳到下一个标记的消息</td></tr><tr><td><code>tui.altScreen.search</code></td><td><code>ctrl+shift+f</code>（Windows 和 WSL 上为 <code>ctrl+f</code>）</td><td>搜索渲染后的对话记录</td></tr><tr><td><code>tui.altScreen.searchNext</code></td><td><code>enter</code>, <code>ctrl+g</code></td><td>搜索时选择下一个匹配项</td></tr><tr><td><code>tui.altScreen.searchPrevious</code></td><td><code>shift+enter</code>, <code>ctrl+shift+g</code></td><td>搜索时选择上一个匹配项</td></tr><tr><td><code>tui.altScreen.searchClose</code></td><td><code>escape</code></td><td>关闭对话记录搜索</td></tr><tr><td><code>tui.altScreen.top</code></td><td><code>ctrl+home</code></td><td>滚动到对话记录开头</td></tr><tr><td><code>tui.altScreen.bottom</code></td><td><code>ctrl+end</code></td><td>滚动到对话记录末尾并跟随新输出</td></tr></tbody></table><h3 id="应用" tabindex="-1">应用 <a class="header-anchor" href="#应用" aria-label="Permalink to &quot;应用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>app.interrupt</code></td><td><code>escape</code></td><td>取消 / 中止</td></tr><tr><td><code>app.clear</code></td><td><code>ctrl+c</code></td><td>清空编辑器（第一次）/ 退出（第二次）</td></tr><tr><td><code>app.exit</code></td><td><code>ctrl+d</code></td><td>退出（编辑器为空时）</td></tr><tr><td><code>app.suspend</code></td><td><code>ctrl+z</code>（Windows 上为无）</td><td>挂起到后台</td></tr><tr><td><code>app.editor.external</code></td><td><code>ctrl+g</code></td><td>在外部编辑器中打开（<code>externalEditor</code>、<code>$VISUAL</code>、<code>$EDITOR</code>、Windows 上为记事本，其他平台为 <code>nano</code>）</td></tr><tr><td><code>app.clipboard.pasteImage</code></td><td><code>ctrl+v</code>（Windows 和 WSL 上为 <code>alt+v</code>）</td><td>在 macOS 上粘贴文件、图片或来自剪贴板的文本</td></tr></tbody></table><p>在原生 Windows 上，<code>app.suspend</code> 没有默认值，因为 Windows 终端不支持 Unix 作业控制。如果手动绑定它，Pi 会显示状态消息而不是挂起。WSL 使用正常的 <code>ctrl+z</code> 和 <code>fg</code> 行为。</p><p><a id="sessions"></a></p><h3 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to &quot;会话&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>app.session.new</code></td><td>无</td><td>开始新会话（<code>/new</code>）</td></tr><tr><td><code>app.session.tree</code></td><td>无</td><td>打开会话树导航器（<code>/tree</code>）</td></tr><tr><td><code>app.session.fork</code></td><td>无</td><td>分叉当前会话（<code>/fork</code>）</td></tr><tr><td><code>app.session.resume</code></td><td>无</td><td>打开会话恢复选择器（<code>/resume</code>）</td></tr><tr><td><code>app.session.togglePath</code></td><td><code>ctrl+p</code></td><td>切换路径显示</td></tr><tr><td><code>app.session.toggleSort</code></td><td><code>ctrl+s</code></td><td>切换排序模式</td></tr><tr><td><code>app.session.toggleNamedFilter</code></td><td><code>ctrl+n</code></td><td>切换仅命名过滤</td></tr><tr><td><code>app.session.rename</code></td><td><code>ctrl+r</code></td><td>重命名会话</td></tr><tr><td><code>app.session.delete</code></td><td><code>ctrl+d</code></td><td>删除会话</td></tr><tr><td><code>app.session.deleteNoninvasive</code></td><td><code>ctrl+backspace</code></td><td>查询为空时删除会话</td></tr></tbody></table><h3 id="模型与思考" tabindex="-1">模型与思考 <a class="header-anchor" href="#模型与思考" aria-label="Permalink to &quot;模型与思考&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>app.model.select</code></td><td><code>ctrl+l</code></td><td>打开模型选择器</td></tr><tr><td><code>app.model.cycleForward</code></td><td><code>ctrl+p</code></td><td>切换到下一个模型</td></tr><tr><td><code>app.model.cycleBackward</code></td><td><code>shift+ctrl+p</code>（Windows 和 WSL 上为 <code>alt+p</code>）</td><td>切换到上一个模型</td></tr><tr><td><code>app.models.save</code></td><td><code>ctrl+s</code></td><td>将选中的默认模型或范围模型配置保存到设置</td></tr><tr><td><code>app.thinking.cycle</code></td><td><code>shift+tab</code></td><td>循环切换思考级别</td></tr><tr><td><code>app.thinking.save</code></td><td><code>ctrl+s</code></td><td>将当前思考级别保存到设置</td></tr><tr><td><code>app.thinking.toggle</code></td><td><code>ctrl+t</code></td><td>折叠或展开思考块</td></tr></tbody></table><h3 id="显示与消息队列" tabindex="-1">显示与消息队列 <a class="header-anchor" href="#显示与消息队列" aria-label="Permalink to &quot;显示与消息队列&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>app.tools.expand</code></td><td><code>ctrl+o</code></td><td>折叠或展开工具输出</td></tr><tr><td><code>app.message.copy</code></td><td><code>ctrl+x</code></td><td>在 <code>/tree</code> 中复制选中的消息；在全屏模式下，当 <code>fullscreenCopyOnSelect</code> 为 <code>false</code> 时复制当前选区，否则复制最后一条助手消息。在 OAuth 登录界面复制登录 URL</td></tr><tr><td><code>app.message.followUp</code></td><td><code>alt+enter</code>（Windows 和 WSL 上为 <code>ctrl+q</code>）</td><td>将后续消息加入队列</td></tr><tr><td><code>app.message.dequeue</code></td><td><code>alt+up</code>（Windows 和 WSL 上为 <code>alt+q</code>）</td><td>将排队的消息恢复到编辑器</td></tr></tbody></table><h3 id="树导航" tabindex="-1">树导航 <a class="header-anchor" href="#树导航" aria-label="Permalink to &quot;树导航&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>app.tree.foldOrUp</code></td><td><code>ctrl+left</code>, <code>alt+left</code></td><td>折叠当前分支段，或跳到上一段开头</td></tr><tr><td><code>app.tree.unfoldOrDown</code></td><td><code>ctrl+right</code>, <code>alt+right</code></td><td>展开当前分支段，或跳到下一段开头或分支末尾</td></tr><tr><td><code>app.tree.editLabel</code></td><td><code>shift+l</code></td><td>编辑所选树节点的标签</td></tr><tr><td><code>app.tree.toggleLabelTimestamp</code></td><td><code>shift+t</code></td><td>切换树中标签时间戳的显示</td></tr><tr><td><code>app.tree.filter.default</code></td><td><code>ctrl+d</code></td><td>将树过滤器设为默认视图</td></tr><tr><td><code>app.tree.filter.noTools</code></td><td><code>ctrl+t</code></td><td>切换隐藏工具结果的树过滤器</td></tr><tr><td><code>app.tree.filter.userOnly</code></td><td><code>ctrl+u</code></td><td>切换仅显示用户消息的树过滤器</td></tr><tr><td><code>app.tree.filter.labeledOnly</code></td><td><code>ctrl+l</code></td><td>切换仅显示带标签条目的树过滤器</td></tr><tr><td><code>app.tree.filter.all</code></td><td><code>ctrl+a</code></td><td>切换显示全部条目的树过滤器</td></tr><tr><td><code>app.tree.filter.cycleForward</code></td><td><code>ctrl+o</code></td><td>向前循环切换树过滤器</td></tr><tr><td><code>app.tree.filter.cycleBackward</code></td><td><code>shift+ctrl+o</code></td><td>向后循环切换树过滤器</td></tr></tbody></table><h3 id="范围模型选择器" tabindex="-1">范围模型选择器 <a class="header-anchor" href="#范围模型选择器" aria-label="Permalink to &quot;范围模型选择器&quot;">​</a></h3><p>在范围模型选择器中（通过 <code>/scoped-models</code> 打开）使用。</p><table tabindex="0"><thead><tr><th>快捷键 ID</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>app.models.enableAll</code></td><td><code>ctrl+a</code></td><td>启用所有模型（或所有匹配当前搜索的模型）</td></tr><tr><td><code>app.models.clearAll</code></td><td><code>ctrl+x</code></td><td>清除所有模型（或所有匹配当前搜索的模型）</td></tr><tr><td><code>app.models.toggleProvider</code></td><td><code>ctrl+p</code></td><td>切换当前 provider 的所有模型</td></tr><tr><td><code>app.models.reorderUp</code></td><td><code>alt+up</code></td><td>在轮换顺序中将所选模型上移</td></tr><tr><td><code>app.models.reorderDown</code></td><td><code>alt+down</code></td><td>在轮换顺序中将所选模型下移</td></tr></tbody></table>`,43)])])}const b=d(r,[["render",a]]);export{u as __pageData,b as default};
